public class ExpTest {
    static double rootNewton(double p, double q) {
        double r = Math.pow(p, 1.0 / q);
        // one Newton refinement step for r^q = p
        r = r - (Math.pow(r, q) - p) / (q * Math.pow(r, q - 1));
        return r;
    }
    public static void main(String[] args) {
        double a = Math.pow(Math.pow(8.0, 1.0 / 3.0), 4);
        System.out.println("root-first (x^(1/b))^a: " + a + "  diff=" + Math.abs(a - 16.0));
        double b = Math.cbrt(Math.pow(8.0, 4));
        System.out.println("cbrt(x^a):              " + b + "  diff=" + Math.abs(b - 16.0));
        double c = rootNewton(Math.pow(8.0, 4), 3);
        System.out.println("pow + 1 Newton step:    " + c + "  diff=" + Math.abs(c - 16.0));
        // check the second test still passes with root-first: 9^(-1/2) = (9^(-1))^(1/2)
        double d = Math.pow(Math.pow(9.0, 1.0 / 2.0), -1);
        System.out.println("root-first 9^(-1/2):    " + d + "  diff=" + Math.abs(d - 1.0/3));
        double e = Math.pow(Math.pow(9.0, -1), 1.0 / 2.0);
        System.out.println("root-first (9^-1)^(1/2):" + e + "  diff=" + Math.abs(e - 1.0/3));
    }
}
